async function adminAccounts(seq){const d=await api('/api/admin/accounts');if(seq!==state.seq)return;$('#accountManagement').innerHTML=ht`<h2>Akkauntlarni boshqarish</h2><p>Restoran egasi, kuryer va gulchi huquqlarini faqat administrator beradi.</p><form id="inviteForm" class="form"><h3>Hamkor akkauntini taklif qilish</h3><label>EMAIL<input type="email" name="email" required></label><label>PROFIL TURI<select name="role"><option value="restaurant_owner">Restoran egasi</option><option value="courier">Kuryer</option><option value="florist">Gulchi</option></select></label><button class="primary">Taklif havolasini yaratish</button><p>Havola 7 kun amal qiladi. Uni kerakli kishiga o‘zingiz yuboring. Akkaunt email tasdiqlangandan keyin faollashadi.</p><div id="inviteResult" role="status"></div></form><div class="separator"></div><h3>Akkauntlar</h3>${d.accounts.map(a=>{const admin=a.role==='admin'||a.id==='sb:4fcd0d25-6ec1-4e10-a15f-8005d683edfe';return ht`<article class="account-row"><div><strong>${esc(a.name)}</strong><p>${esc(a.email||a.phone)}</p><span class="badge">${admin?t('Administrator'):roleLabel(a.role==='owner'?'restaurant_owner':a.role)}</span> <span>${a.status==='suspended'?t('To‘xtatilgan'):t('Faol')}</span></div>${admin?'':ht`<div class="row-actions"><select aria-label="Profil turi" data-account-role="${esc(a.id)}">${['customer','restaurant_owner','courier','florist'].map(r=>ht`<option value="${r}" ${(a.role==='owner'?'restaurant_owner':a.role)===r?'selected':''}>${roleLabel(r)}</option>`).join('')}</select><button class="quiet" data-role-save="${esc(a.id)}">Rolni saqlash</button><button class="quiet" data-account-status="${esc(a.id)}" data-next="${a.status==='active'?'suspended':'active'}">${a.status==='active'?t('To‘xtatish'):t('Faollashtirish')}</button>${a.birth_date?ht`<button type="button" class="quiet" data-birth-reset="${esc(a.id)}">🎂 ${t(t('Tug‘ilgan sanani tiklash'))}</button>`:''}${a.role==='courier'?ht`<button class="quiet" data-courier="${esc(a.id)}" data-approved="${a.courier_approved?'0':'1'}">${a.courier_approved?t('Yetkazib berishni to‘xtatish'):t('Yetkazib berishga ruxsat')}</button>`:''}</div>`}</article>`}).join('')}<h3>Hamkorlik arizalari</h3>${d.requests.length?d.requests.map(q=>ht`<article class="row"><div><strong>${esc(q.name)}</strong><p>${esc(q.email)} · ${roleLabel(q.role)}</p><p>${esc(q.note)}</p><span>${statusName[q.status]||q.status}</span></div>${q.status==='pending'?ht`<div class="row-actions"><button class="primary" data-request="${esc(q.user_id)}" data-action="approve-request">Tasdiqlash</button><button class="quiet" data-request="${esc(q.user_id)}" data-action="reject-request">Rad etish</button></div>`:''}</article>`).join(''):lh('<p>Hali arizalar yo‘q.</p>')}<h3>Takliflar</h3>${d.invites.map(i=>ht`<div class="row"><span>${esc(i.email)} · ${roleLabel(i.role)}<br><small>${i.accepted_by?t('Qabul qilingan'):i.revoked?t('Bekor qilingan'):new Date(i.expires_at)<new Date()?t('Muddati tugagan'):t('Kutilmoqda')} · ${esc(i.expires_at.slice(0,10))}</small></span>${!i.accepted_by&&!i.revoked?ht`<button class="quiet" data-revoke="${esc(i.id)}">Bekor qilish</button>`:''}</div>`).join('')||lh('<p>Takliflar yo‘q.</p>')}<details><summary>Administrator amallari jurnali</summary>${d.audit.map(a=>ht`<div class="audit-row"><small>${esc(a.created_at)} · ${esc(a.action)}</small><p>${esc(a.target_id)}</p><code>${esc(a.details)}</code></div>`).join('')||lh('<p>Hali yozuvlar yo‘q.</p>')}</details>`;
const act=async(button,payload)=>{button.disabled=true;try{await api('/api/admin/accounts','POST',payload);await adminAccounts(seq)}catch(e){notify(e.message);button.disabled=false}};
$('#inviteForm').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{const d=await api('/api/admin/accounts','POST',{action:'invite',...Object.fromEntries(new FormData(e.currentTarget))});$('#inviteResult').innerHTML=ht`<label>Taklif havolasi<input readonly value="${esc(d.url)}" id="inviteLink"></label><p>Email avtomatik yuborilmagan. Havolani nusxalab yuboring.</p>`;$('#inviteLink').select()}catch(e){notify(e.message)}finally{b.disabled=false}};
document.querySelectorAll('[data-role-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.roleSave,role=document.querySelector('[data-account-role="'+CSS.escape(id)+'"]').value;if(confirm(t(t('Akkaunt huquqlarini o‘zgartirasizmi?'))))act(b,{action:'role',id,role})});document.querySelectorAll('[data-account-status]').forEach(b=>b.onclick=()=>act(b,{action:'status',id:b.dataset.accountStatus,status:b.dataset.next}));document.querySelectorAll('[data-birth-reset]').forEach(b=>b.onclick=()=>{if(confirm(t(t('Mijozning tug‘ilgan sanasi o‘chirilsinmi? U sanani qayta bir marta kiritadi.'))))act(b,{action:'birth_reset',id:b.dataset.birthReset})});document.querySelectorAll('[data-courier]').forEach(b=>b.onclick=()=>act(b,{action:'courier-permission',id:b.dataset.courier,approved:b.dataset.approved==='1'}));document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>act(b,{action:b.dataset.action,id:b.dataset.request}));document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>act(b,{action:'revoke-invite',id:b.dataset.revoke}));
}
async function invitePage(seq){const token=location.hash.split('/')[2]||'';if(!/^[a-f0-9]{64}$/.test(token))throw Error(t(t('Taklif havolasi noto‘g‘ri.')));sessionStorage.setItem('rf-invite',token);page(t('Hamkor taklifi'),ht`<div class="panel compact"><h2>RestaurantFoods jamoasiga qo‘shiling</h2><p>Taklif yuborilgan email bilan kiring yoki akkaunt yarating. Huquqlar faqat email tasdiqlangandan keyin beriladi.</p>${state.user?lh('<button id="acceptInvite" class="primary">Taklifni qabul qilish</button>'):lh('<a class="primary" href="#/signup">Akkaunt yaratish</a><a class="quiet" href="#/login">Kirish</a>')}</div>`);if($('#acceptInvite'))$('#acceptInvite').onclick=async e=>{e.target.disabled=true;try{await api('/api/profile','POST',{action:'accept-invite',token});sessionStorage.removeItem('rf-invite');state.user=(await api('/api/me')).user;location.hash=homeFor(state.user)}catch(err){notify(err.message);e.target.disabled=false}}}
function legalPage(kind){page(kind==='privacy'?t('Maxfiylik siyosati'):t('Foydalanish shartlari'),ht`<section class="panel compact">${kind==='privacy'?lh('<h2>Ma’lumotlaringiz</h2><p>RestaurantFoods akkaunt, bron va buyurtmalarni yuritish uchun ism, tasdiqlangan email yoki telefon, buyurtma va bron ma’lumotlarini saqlaydi. Kirish Supabase orqali, botlardan himoya Cloudflare orqali ishlaydi.</p><p>Yetkazib berish manzili faqat buyurtmaga aloqador mijoz, restoran, biriktirilgan kuryer va administratorga ko‘rinadi. Kuryer GPS joylashuvi faqat ruxsat bilan faol yetkazib berishda ulashiladi. Til va mavzu tanlovi qurilmada saqlanadi.</p><p>Ma’lumotlarni tuzatish yoki o‘chirish uchun supportga murojaat qiling. Qonuniy va hisob-kitob ehtiyojlari uchun ayrim yozuvlar saqlanishi mumkin.</p>'):lh('<h2>Xizmatdan foydalanish</h2><p>Faqat haqiqiy ma’lumot kiriting. Akkaunt paroli va tasdiqlash kodini boshqalarga bermang. Restoran taom, narx, mavjudlik va bronni tasdiqlash uchun javobgar.</p><p>Bron va buyurtma yuborilishi tasdiq degani emas: holatini shaxsiy panelda tekshiring. Bekor qilish imkoniyati bron yoki buyurtma holatiga bog‘liq. Hozir to‘lov restoran yoki yetkazib berish vaqtida amalga oshiriladi; onlayn to‘lov ulanmagan.</p><p>Sharhlar haqiqiy tajribaga asoslanishi kerak. Firibgarlik, noqonuniy kontent va boshqalarning ma’lumotidan ruxsatsiz foydalanish taqiqlanadi.</p>')}<a class="quiet" href="#/support">Yordam va aloqa</a></section>`)}
